source(file.path(here,'reference_supplement_data.R'),local=TRUE)
set.seed(SEED)
## Figures -----------------------------------------------------------------------
message("Building R-only publication figures and panel-level source data")
write_tsv(recon,prev("figures/source_data/panel_A_reconciliation.tsv")); write_tsv(coverage,prev("figures/source_data/panel_B_coverage.tsv")); write_tsv(stagea_stats,prev("figures/source_data/panel_C_stageA.tsv")); write_tsv(null_summary,prev("figures/source_data/panel_D_nulls.tsv")); write_tsv(dall,prev("figures/source_data/panel_E_scores.tsv")); write_tsv(ood_models,prev("figures/source_data/panel_F_ood.tsv"))
pA<-ggplot(recon,aes(x=reorder(count_label,count),y=count,fill=authority))+geom_col(width=.65)+geom_text(aes(label=count),hjust=1.1,size=2.4)+coord_flip()+scale_fill_manual(values=c(AUTHORITATIVE_FOR_DEPLOYMENT=unname(palette["accent"]),HISTORICAL="#C7C7C7"))+labs(x=NULL,y="Shared genes",title="No refitting / no human calibration")+theme(legend.position="none",plot.title=element_text(size=7.2))
coverage[,human_detection_coverage:=human_detected_count/selected_gene_count]
covlong<-melt(coverage,id.vars=c("model_family","selected_gene_count","mapped_one_to_one_count","human_detected_count"),measure.vars=c("raw_gene_coverage","human_detection_coverage","absolute_weight_coverage"),variable.name="coverage",value.name="fraction")
covlong[,label:=fcase(coverage=="raw_gene_coverage",sprintf("%.0f%%\n%d",100*fraction,mapped_one_to_one_count),coverage=="human_detection_coverage",sprintf("%.0f%%\n%d",100*fraction,human_detected_count),default=sprintf("%.0f%%",100*fraction))]
covlong[,coverage:=factor(coverage,levels=c("raw_gene_coverage","human_detection_coverage","absolute_weight_coverage"),labels=c("Mapped","Human detected","|Weight|"))]
pB<-ggplot(covlong,aes(model_family,fraction,fill=coverage))+geom_col(position=position_dodge(.72),width=.68)+geom_text(aes(label=label),position=position_dodge(.72),vjust=-.25,size=1.9)+coord_cartesian(ylim=c(0,1.12))+labs(x=NULL,y="Coverage",title="Mapping, detection and |weight| coverage")+theme(plot.title=element_text(size=7.2),legend.position="bottom",legend.title=element_blank())
pcdat<-stagea_stats[analysis%in%c("elasticnet_hvg_3000","pca_versionB_3000")]
pC<-ggplot(pcdat,aes(model_family,spearman_correlation,fill=model_family))+geom_col(width=.6)+geom_text(aes(y=spearman_correlation/2,label=sprintf("rho %.2f\nsign %.0f%%\nn=%d\nnull p=%.3f",spearman_correlation,100*sign_concordance,gene_count,matched_null_empirical_p)),size=1.95)+coord_cartesian(ylim=range(c(-.075,.01,pcdat$spearman_correlation*1.25)))+labs(x=NULL,y="Spearman rho (signed t)",title="Stage A standardized effects")+scale_fill_manual(values=palette)+theme(legend.position="none",plot.title=element_text(size=7.2))
null_summary[,null_short:=factor(null_type,levels=c("original_matched_random_signature_primary","matched_gene_null","weight_sign_permutation_actual_mapped_features","gtex_age_bracket_label_permutation"),labels=c("Primary matched random","Matched gene","Weight/sign perm.","Age-label perm."))]
pD<-ggplot(null_summary,aes(model_family,observed_statistic,colour=model_family))+geom_errorbar(aes(ymin=null_2.5_percentile,ymax=null_97.5_percentile),colour="#777777",width=.12)+geom_point(size=2)+facet_wrap(~null_short,scales="free_y")+scale_colour_manual(values=palette)+labs(x=NULL,y="Observed; empirical 2.5–97.5% null interval",title="Specificity nulls (10,000 permutations)")+theme(legend.position="none",axis.text.x=element_text(angle=30,hjust=1),plot.title=element_text(size=7.2),strip.text=element_text(size=5.8))
means<-dall[,.(mean=mean(cross_species_mouse_ovarian_clock_score),se=sd(cross_species_mouse_ovarian_clock_score)/sqrt(.N),n=.N),by=.(model_family,age_bracket,age_order)]
bn<-unique(means[,.(age_order,n)])
pE<-ggplot(dall,aes(age_order,cross_species_mouse_ovarian_clock_score,colour=model_family))+geom_jitter(width=.12,alpha=.25,size=.7)+geom_errorbar(data=means,aes(y=mean,ymin=mean-1.96*se,ymax=mean+1.96*se),width=.12,linewidth=.4)+geom_line(data=means,aes(y=mean),linewidth=.6)+geom_point(data=means,aes(y=mean),size=1.4)+geom_text(data=bn,aes(x=age_order,y=3.35,label=paste0("n=",n)),inherit.aes=FALSE,colour="#555555",size=1.65)+scale_x_continuous(breaks=1:6,labels=levels(meta$age_bracket))+coord_cartesian(ylim=c(-3.3,3.65))+scale_colour_manual(values=palette)+labs(x="GTEx age bracket",y="Frozen score (SD)",title="Frozen scores: donors, means and 95% CIs")+theme(axis.text.x=element_text(angle=35,hjust=1),legend.position="bottom",plot.title=element_text(size=7.2))
pfdat<-rbindlist(list(data.table(model_family="agreement",value=agree[dataset=="GTEx_193_donors",pearson_r],metric="GTEx model agreement"),dall[,.(value=cor(age_order,projection_ood_distance,method="spearman")),by=model_family][,metric:="Age–OOD Spearman rho"]),fill=TRUE)
pfdat[,model_family:=factor(model_family,levels=c("agreement","elasticnet","pca_glmnet"),labels=c("GTEx model r","ElasticNet\nage–OOD rho","PCA/glmnet\nage–OOD rho"))]
pF<-ggplot(pfdat,aes(model_family,value,fill=model_family))+geom_col(width=.6)+geom_hline(yintercept=0,linewidth=.25)+scale_fill_manual(values=c("GTEx model r"="#777777","ElasticNet\nage–OOD rho"=unname(palette["elasticnet"]),"PCA/glmnet\nage–OOD rho"=unname(palette["pca_glmnet"])))+coord_cartesian(ylim=range(c(-.7,.15,pfdat$value*1.2)))+geom_text(aes(label=sprintf("%.2f",value),y=ifelse(value<0,value+.04,value+.025)),size=2)+labs(x=NULL,y="Correlation",title="Agreement and model-specific age–OOD")+theme(legend.position="none",axis.text.x=element_text(angle=25,hjust=1),plot.title=element_text(size=7.2))
fullfig<-wrap_plots(pA,pB,pC,pD,pE,pF,ncol=2,heights=c(1,1.05,1.15))+plot_annotation(tag_levels="A",theme=theme(plot.margin=margin(12,6,6,10)))&theme(plot.tag=element_text(face="bold",size=8),plot.tag.position=c(.01,.99))
save_bundle(fullfig,prev("figures/supplement_complete_stageA_stageB_A_to_F"),183,240)

pnull<-ggplot(null_source,aes(null_statistic,fill=model_family))+geom_histogram(bins=60,alpha=.55,position="identity")+geom_vline(aes(xintercept=observed_statistic,colour=model_family),linewidth=.5)+facet_grid(model_family~null_type,scales="free")+scale_fill_manual(values=palette)+scale_colour_manual(values=palette)+labs(x="Null age-slope statistic",y="Count",title="Full null distributions; vertical line is observed")+theme(legend.position="none")
save_bundle(pnull,prev("figures/supplement_stageB_null_distributions"),183,150)
